/**
 * Bundled, trimmed copy of hasaneyldrm/exercises-dataset (MIT metadata/instructions,
 * media © Gym visual — see NOTICE below). Source: assets/data/exercises_dataset.json,
 * 1,324 entries, generated by dropping every language but Spanish instructions and
 * every field Garou doesn't use. Regenerate with the same trim if the upstream
 * dataset updates (id, name, body_part, equipment, target, muscle_group,
 * secondary_muscles, media_id, image, gif_url, instruction_steps.es).
 *
 * NOTICE — media license (verified against openGym, which uses the same dataset):
 * the GIFs/images are attributed to Gym visual via a permission granted to the
 * upstream dataset specifically, not clearly transferable; ExerciseDB/AscendAPI
 * (the dataset's own upstream source) separately claims ownership and prohibits
 * redistributing the media as a standalone package. Garou never bundles or persists
 * the media itself (see cdnUrl below) — only this trimmed text metadata, which the
 * dataset's own code/metadata MIT license covers. Personal-use decision, already
 * made with the user — see project memory.
 */

// Loaded via require() INSIDE this function (not a top-level import) so Hermes
// only parses this ~1MB JSON the first time something actually calls loadDataset(),
// not on every app launch.
export interface DatasetExercise {
  id: string; // 4-digit dataset id, e.g. "0001"
  name: string; // English name (dataset has no Spanish exercise names, only instructions)
  bodyPart: string;
  equipment: string;
  target: string;
  muscleGroup: string;
  secondaryMuscles: string[];
  mediaId: string;
  image: string; // relative path, e.g. "images/0001-2gPfomN.jpg"
  gif: string; // relative path, e.g. "videos/0001-2gPfomN.gif"
  stepsEs: string[];
}

// Pinned to a specific commit (not a floating branch) so the app never breaks if
// the upstream repo's structure changes — matches openGym's own approach.
const DATASET_COMMIT = '7455efae41b330c265e7cd4b78dfa848e7ce5ebd';
const CDN_BASE = `https://cdn.jsdelivr.net/gh/hasaneyldrm/exercises-dataset@${DATASET_COMMIT}`;

/** Full https URL for a dataset-relative path (e.g. def.gif or def.image). expo-image caches it to disk on first view. */
export function datasetMediaUrl(relativePath: string): string {
  return `${CDN_BASE}/${relativePath}`;
}

let _cache: DatasetExercise[] | null = null;

/** Lazy-loaded, parsed once per app session and kept in memory after that. */
export function loadDataset(): DatasetExercise[] {
  if (_cache) return _cache;
  // eslint-disable-next-line @typescript-eslint/no-var-requires
  _cache = require('../../assets/data/exercises_dataset.json') as DatasetExercise[];
  return _cache;
}

function normalize(s: string): string {
  // \p{Diacritic} (Unicode property escape, needs the /u flag) strips the
  // combining marks NFD decomposition leaves behind (e.g. "e" + acute-accent
  // mark for the letter that reads as "e with an accent"), so search matches
  // across languages regardless of accents. Deliberately no literal accented
  // character anywhere in this file's source — this codebase has hit mojibake
  // from that before (see seed.ts).
  return s.toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu, '');
}

/**
 * Substring search across name, target, muscleGroup, secondaryMuscles, bodyPart,
 * equipment. Every whitespace-separated token in `query` must match somewhere —
 * same rule openGym's Library search uses. Returns at most `limit` results.
 */
export function searchDataset(query: string, limit = 60): DatasetExercise[] {
  const dataset = loadDataset();
  const trimmed = query.trim();
  if (!trimmed) return dataset.slice(0, limit);

  const tokens = normalize(trimmed).split(/\s+/).filter(Boolean);
  const results: DatasetExercise[] = [];

  for (const ex of dataset) {
    const corpus = normalize(
      [ex.name, ex.target, ex.muscleGroup, ...ex.secondaryMuscles, ex.bodyPart, ex.equipment].join(' ')
    );
    if (tokens.every((t) => corpus.includes(t))) {
      results.push(ex);
      if (results.length >= limit) break;
    }
  }
  return results;
}

export function getDatasetExerciseById(id: string): DatasetExercise | undefined {
  return loadDataset().find((e) => e.id === id);
}
